import type { Metadata, Viewport } from "next";
import "./globals.css";
import { APP_DESCRIPTION } from "@/lib/appMeta";

export const metadata: Metadata = {
  title: "APEX Engine",
  description: APP_DESCRIPTION,
  applicationName: "APEX Engine",
  // "Add to Home Screen" (iOS Safari and Android Chrome): opens full screen with the APEX name. The web app manifest is app/manifest.ts and the
  // icons are generated by app/icons/[size]/route.tsx. There is deliberately NO service worker and no offline cache of personal data.
  appleWebApp: { capable: true, title: "APEX", statusBarStyle: "black" },
  formatDetection: { telephone: false },
  icons: { icon: [{ url: "/icons/32", sizes: "32x32", type: "image/png" }, { url: "/icons/192", sizes: "192x192", type: "image/png" }], apple: "/icons/180" },
};
// Pinch-zoom is left enabled on purpose (accessibility).
// viewportFit "cover" lets env(safe-area-inset-*) work on notched phones; interactiveWidget "resizes-content" makes an open on-screen keyboard shrink the
// layout (Android Chrome) so a bottom composer sits above it instead of behind it.
export const viewport: Viewport = { themeColor: "#06080b", width: "device-width", initialScale: 1, colorScheme: "dark", viewportFit: "cover", interactiveWidget: "resizes-content" };

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
